class PreflightValidator:
    def __init__(self, config, budget_ceiling_usd):
        self.config = config
        self.budget = budget_ceiling_usd
    def validate(self):
        if not 0 < self.budget <= 20.0:
            return {'verdict': 'NO-GO', 'reason': 'budget_ceiling_usd must be in (0, 20.0]'}
        checks = [self.check_hardware(), self.check_dependencies(), self.check_spending_cap(), self.check_dry_run()]
        verdict = 'GO' if all(checks) else 'NO-GO'
        return {'verdict': verdict, 'checks_passed': checks, 'budget_limit': self.budget}
